Unused_AdjustBgMosaic.body:
u16 mosaic = GetGpuReg(REG_OFFSET_MOSAIC);
    s16 bgH = mosaic & 0xF;
    s16 bgV = (mosaic >> 4) & 0xF;

    mosaic &= 0xFF00;  

    switch (mode)
    {
    case BG_MOSAIC_SET_HV:
    default:
        bgH = val & 0xF;
        bgV = val >> 0x4;
        break;
    case BG_MOSAIC_SET_H:
        bgH = val & 0xF;
        break;
    case BG_MOSAIC_ADD_H:
        if ((bgH + val) > 0xF)
        {
            bgH = 0xF;
        }
        else
        {
            bgH += val;
        }
        break;
    case BG_MOSAIC_SUB_H:
        if ((bgH - val) < 0)
        {
            bgH = 0x0;
        }
        else
        {
            bgH -= val;
        }
        break;
    case BG_MOSAIC_SET_V:
        bgV = val & 0xF;
        break;
    case BG_MOSAIC_ADD_V:
        if ((bgV + val) > 0xF)
        {
            bgV = 0xF;
        }
        else
        {
            bgV += val;
        }
        break;
    case BG_MOSAIC_SUB_V:
        if ((bgV - val) < 0)
        {
            bgV = 0x0;
        }
        else
        {
            bgV -= val;
        }
        break;
    }

    mosaic |= ((bgV << 0x4) & 0xF0);
    mosaic |= (bgH & 0xF);

    SetGpuReg(REG_OFFSET_MOSAIC, mosaic);

    return mosaic;

